def main():
    assert len(SOURCES) == 24
    assert len(DRAFTS) == 24
    assert {s['number'] for s in SOURCES} == set(DRAFTS)
    fragment_dir = ROOT / 'fragments'
    fragment_dir.mkdir(exist_ok=True)
    answer = []
    for source in SOURCES:
        xml, reason, notes = DRAFTS[source['number']]
        fragment_path = fragment_dir / (source['number'] + '.xml')
        fragment_path.write_text(xml + '\n')
        answer.append({
            **{key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')},
            'proposed_xml': fragment_path.read_text().strip(),
            'reason': reason,
            'review_notes': notes,
            'status': 'rewrite_draft',
        })
    (ROOT / 'answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
    print(f'answer.json : {len(answer)} articles, {sum(len(a["proposed_xml"]) for a in answer)} caractères de texte proposé')


if __name__ == '__main__':
    main()
